class Solution {
public:
    vector<string> assignUmbrella(vector<int>& rain) {
        int n = (int)rain.size();
        vector<string> ans(n);
        int alice = 0, bob = 0;
        for (int i = 0; i < n; i++) {
            bool aliceNeeds = (i + 1 < n) && rain[i] == 1 && rain[i + 1] == 1;
            bool bobNeeds = rain[i] == 1;
            if (aliceNeeds && bobNeeds) {
                if (alice <= bob) {
                    ans[i] = "Alice";
                    alice++;
                } else {
                    ans[i] = "Bob";
                    bob++;
                }
            } else if (bobNeeds) {
                ans[i] = "Bob";
                bob++;
            } else {
                ans[i] = "None";
            }
        }
        return ans;
    }
};
